/* Chrome is a read-only projection of Catalog V2 equipment, not another inventory. */
(function(root){
 'use strict';
 const V=root.ND_CATALOG_V2||(typeof require==='function'?require('./catalog-v2.js'):null);
 const zones=[['head','Голова и глаза','head'],['nerves','Нервная система','network'],['arms','Руки','arms'],['torso','Торс и органы','torso'],['skin','Кожа и скелет','layers'],['legs','Ноги','legs'],['system','Системные','chrome']];
 const states=new Map();
 const h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const name=item=>item.displayName||item.name||'Неизвестная система';
 const sign=n=>n<0?'−'+Math.abs(n):'+'+n;
 function placement(value){const raw=typeof value==='string'?value.trim():'',s=raw.toLocaleLowerCase('ru').replace(/ё/g,'е');
  const rules=[['head',/глаз|голов|череп|мозг|оптик|зрени|eye|head|brain|optic/],['nerves',/нерв|нейрон|спинн|nerv|neural|spinal/],['arms',/рук|рук[аи]|кист|пальц|предплеч|плеч|arm|hand/],['torso',/торс|орган|легк|сердц|груд|живот|внутрен|torso|organ|lung|heart|chest/],['skin',/кож|скелет|кост|skin|skelet|bone/],['legs',/ног|стоп|бедр|колен|leg|foot|feet/]];
  const ids=rules.filter(([id,re])=>re.test(s)&&!(id==='head'&&/спинн.*мозг/.test(s))).map(([id])=>id);
  if(!ids.length||/любо|неопредел|на выбор|(?:^|\s)или(?:\s|$)|\bor\b/.test(s))return {id:'system',additional:[],raw};
  return {id:ids[0],additional:ids.slice(1),raw};
 }
 function installed(c,catalog){return V.normalizeCharacter(c,catalog).equipmentItems.map(instance=>({instance,item:V.resolve(catalog,instance.catalogId)||instance.snapshot})).filter(({instance:x,item})=>item&&['implant','neurodeck'].includes(item.classId)&&x.location==='installed'&&x.quantity>0&&x.equipped!==false).map(({instance,item})=>({id:instance.instanceId,instance,item,zone:placement(item.equipment?.placement??item.placement),slots:Number(item.equipment?.chromeSlots??item.slots)||0}));}
 function model(c,catalog){const rows=installed(c,catalog),stats=V.calculateCharacterStats(c,catalog);return {rows,stats,counts:Object.fromEntries(zones.map(([id])=>[id,rows.filter(x=>x.zone.id===id).length]))};}
 function state(){const key=typeof cloudRecord!=='undefined'&&cloudRecord?.id||'local';if(!states.has(key))states.set(key,{zone:'all',selected:null});return states.get(key);}
 function selection(m,s){const rows=m.rows.filter(x=>s.zone==='all'||x.zone.id===s.zone);if(!rows.some(x=>x.id===s.selected))s.selected=rows[0]?.id||null;return {rows,selected:rows.find(x=>x.id===s.selected)};}
 function labelTarget(e,data){if(e.type==='derived_modifier')return {max_hp:'Максимум здоровья',armor:'Защита',chrome_capacity:'Вместимость Хрома'}[e.targetId]||e.targetId;const ids=e.targetType==='attribute'?V.attributeIds:V.skillIds,entries=e.targetType==='attribute'?data.attributes:data.skills;return entries[ids.indexOf(e.targetId)]?.name||e.targetId||'';}
 function effectText(e,data){const text=e.description||e.rulesText;if(text)return text;const target=labelTarget(e,data),conditions=e.conditions||{},context=[];if(conditions.distanceMin!=null||conditions.distanceMax!=null)context.push('Дистанция '+(conditions.distanceMin??0)+'–'+(conditions.distanceMax??'∞'));if(conditions.ownWeapon)context.push('С этим оружием');if(conditions.weaponId)context.push('Оружие: '+conditions.weaponId);if(conditions.attributeId)context.push('Характеристика: '+labelTarget({targetType:'attribute',targetId:conditions.attributeId},data));if(conditions.skillId)context.push('Навык: '+labelTarget({targetType:'skill',targetId:conditions.skillId},data));return [Number.isFinite(e.value)?sign(e.value)+' · '+target:target,...context].filter(Boolean).join(' · ');}
 function effects(row,c,catalog,data){const stats=V.calculateCharacterStats(c,catalog),permanent=[];for(const [type,entries] of [['attributes',data.attributes],['skills',data.skills]]){const ids=type==='attributes'?V.attributeIds:V.skillIds;ids.forEach((id,i)=>{const sources=stats[type][id].sources.filter(x=>x.instanceId===row.id);const value=sources.reduce((n,x)=>n+x.value,0);if(value)permanent.push(sign(value)+' · '+entries[i].name);});}
  // Derive marginal resource bonuses with the same calculator, including stacking and clamps.
  const without=V.normalizeCharacter(c,catalog);const removed=without.equipmentItems.find(x=>x.instanceId===row.id);removed.location='inventory';removed.equipped=false;const before=V.calculateCharacterStats(without,catalog);
  for(const [label,value] of [['Максимум здоровья',stats.maxHP-before.maxHP],['Защита',stats.armor-before.armor],['Вместимость Хрома',stats.chrome.capacity-before.chrome.capacity]])if(value)permanent.push(sign(value)+' · '+label);
  const duration={while_installed:'При установке',while_equipped:'При экипировке',while_loaded:'При загрузке',while_learned:'После изучения'};
  const other=(row.item.effects||[]).filter(e=>!(['stat_modifier','derived_modifier'].includes(e.type)&&e.duration==='while_installed')).map(e=>({kind:e.type==='conditional_modifier'?'Условный эффект':e.type==='temporary_effect'?'Временный эффект':e.type==='rules_only'?'Особые правила':duration[e.duration]||'Эффект',text:effectText(e,data)})).filter(x=>x.text);
  return {permanent,other};
 }
 function icon(id){const custom={head:'M7 20v-4C2 12 4 3 11 3c5 0 7 3 7 6l3 4h-3v4h-6v4 M8 7h5 M8 10h5',arms:'m3 19 4-9 4 2 4-7 4 2-3 8-6 6Z M16 4l2-2 3 2-1 3',torso:'M11 4v9 M13 4v9 M8 7C3 9 2 18 5 20c3 2 5-2 5-5V9 M16 7c5 2 6 11 3 13-3 2-5-2-5-5V9',legs:'m8 3 4 7-2 5-3 7H3l4-8-2-5 M16 3l-2 7 3 5 4 7h-4l-5-7',layers:'m3 7 9-5 9 5-9 5Z M3 12l9 5 9-5 M3 17l9 5 9-5'};return custom[id]?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+custom[id]+'"/></svg>':root.ND_DOSSIER.uiIcon(id);}
 // Coordinates share the 500 × 650 image stage; installation rules stay in placement()/model().
 const bodyPoints={head:[49,12.2],nerves:[50,24.7],arms:[38,40.5],torso:[55,35.7],skin:[42,52.4],legs:[55,73.2]};
 function bodyArt(){return '<div class="chrome-anatomy" aria-hidden="true"><img class="chrome-body-image" src="assets/img/body-front.png?v=889a437cd60f" width="971" height="1620" alt="" decoding="async"><div class="chrome-scan-hud"><span>WD-CHROME / BODY SCAN</span><svg class="chrome-scan-trace" viewBox="0 0 100 30" fill="none"><path d="M0 15h25l4-4 4 7 5-15 5 25 4-13h12l4-6 5 11 4-5h28"/></svg><small>FRONT / ANATOMICAL VIEW</small></div><svg class="chrome-scan-overlay" viewBox="0 0 500 650" fill="none" preserveAspectRatio="none">'+zones.filter(([id])=>id!=='system').map(([id])=>{const [px,py]=bodyPoints[id],x=px*5,y=py*6.5,end={head:[100,96],nerves:[395,174],arms:[90,275],torso:[400,338],skin:[100,469],legs:[400,560]}[id];return '<g class="chrome-anatomy-node" data-body-zone="'+id+'"><path class="chrome-connector" d="M'+x+' '+y+' L'+end[0]+' '+end[1]+'"/><circle class="chrome-node-ring" cx="'+x+'" cy="'+y+'" r="10"/><circle cx="'+x+'" cy="'+y+'" r="4"/></g>';}).join('')+'</svg></div>';}
 function nodeTargets(m){return '<div class="chrome-node-controls">'+zones.filter(([id])=>id!=='system').map(([id,label])=>'<button type="button" class="chrome-node-target" tabindex="-1" data-chrome-zone="'+id+'" aria-label="'+label+': '+m.counts[id]+' установлено" style="left:'+bodyPoints[id][0]+'%;top:'+bodyPoints[id][1]+'%"></button>').join('')+'</div>';}
 function body(m,s){return `<section class="chrome-panel chrome-body" aria-labelledby="chrome-body-title"><header class="chrome-panel-head"><h2 id="chrome-body-title">Схема тела</h2><small>Фронтальная проекция</small></header><div class="chrome-body-stage">${bodyArt()}${nodeTargets(m)}<div class="chrome-zone-controls" aria-label="Зоны тела">${zones.filter(([id])=>id!=='system').map(([id,label,i])=>`<button type="button" class="chrome-zone chrome-zone-${id} ${m.counts[id]?'has-installations':''}" data-chrome-zone="${id}" aria-pressed="${s.zone===id}" aria-label="${label}: ${m.counts[id]} установлено">${icon(i)}<span><strong>${label}</strong><small>${m.counts[id]} установлено</small></span></button>`).join('')}</div></div><button class="chrome-system-zone" data-chrome-zone="system" aria-pressed="${s.zone==='system'}">${icon('chrome')}<span>Системные</span><b>${m.counts.system}</b></button></section>`;}
 function load(m){const {used,capacity,free}=m.stats.chrome,n=Math.max(0,Math.trunc(capacity)),over=free<0;return `<section class="chrome-load chrome-panel ${over?'is-overloaded':''}" aria-label="Нейронная нагрузка"><div class="chrome-load-icon">${icon('layers')}</div><div class="chrome-load-main"><div class="chrome-load-title"><h2>Нейронная нагрузка</h2><strong>${used}<small> / ${capacity}</small></strong></div><div class="chrome-load-meter" role="img" aria-label="Использовано ${used} из ${capacity} слотов">${n>0&&n<=20?Array.from({length:n},(_,i)=>'<i class="'+(i<used?'is-used':'')+'"></i>').join(''):'<span class="chrome-load-fill" style="width:'+Math.min(100,capacity>0?used/capacity*100:used?100:0)+'%"></span>'}</div></div><p>${over?'Превышение: '+(-free)+'<br>Киберпсихоз: '+Math.max(0,used-capacity):'Свободно слотов: <b>'+free+'</b>'}</p></section>`;}
 function filters(m,s){return `<div class="chrome-filters" aria-label="Фильтр по зоне">${[['all','Все'],...zones].map(([id,label])=>`<button type="button" data-chrome-zone="${id}" aria-pressed="${s.zone===id}">${label} <span>(${id==='all'?m.rows.length:m.counts[id]})</span></button>`).join('')}</div>`;}
 function art(row,cls){return typeof catalogIcon==='function'?catalogIcon(row.item,cls):'<img class="'+cls+'" src="assets/item-icons/'+(row.item.classId==='neurodeck'?'neurodeck':'implant')+'.webp" alt="">';}
 function list(m,s,rows){return `<section class="chrome-panel chrome-installed" aria-labelledby="chrome-installed-title"><header class="chrome-panel-head"><h2 id="chrome-installed-title">Установленные импланты</h2><small>Всего: ${m.rows.length}</small></header>${filters(m,s)}<div class="chrome-implant-list">${rows.map(row=>`<button type="button" class="chrome-implant ${s.selected===row.id?'is-selected':''}" data-chrome-select="${h(row.id)}" aria-pressed="${s.selected===row.id}">${art(row,'chrome-item-icon')}<span class="chrome-implant-copy"><strong>${h(name(row.item))}</strong><small>${h(zones.find(([id])=>id===row.zone.id)[1])}${row.item.subtype?' · '+h(row.item.subtype):''}</small></span><span class="chrome-slot-label">${row.slots}<small> сл.</small></span><span class="chrome-arrow" aria-hidden="true">›</span></button>`).join('')||`<div class="chrome-empty">${icon('chrome')}<h3>${m.rows.length?'В этой зоне нет установок':'Импланты не установлены'}</h3>${m.rows.length?'':'<p>Установка и извлечение выполняются через снаряжение</p>'}</div>`}</div></section>`;}
 function detail(row,c,catalog,data){if(!row)return `<aside class="chrome-panel chrome-detail chrome-detail-empty" aria-label="Подробности системы">${icon('chrome')}<h2>Данные системы</h2><p>Выбери установленный имплант на схеме или в списке</p></aside>`;const item=row.item,eq=item.equipment||{},fx=effects(row,c,catalog,data),facts=[['Занимает слотов',row.slots],['Подтип',item.subtype],['Место установки',row.zone.raw],...(item.classId==='neurodeck'?[['Бонус ко Взлому',eq.hackingBonus==null?null:sign(eq.hackingBonus)],['Защита',item.stats?.defense??item.stats?.protection],['Вместимость Червей',eq.wormCapacity],['Вместимость Демонов',eq.demonCapacity]]:[])],technical=[['Производитель',item.manufacturer],['Активация',({passive:'Пассивная',active:'Активная'})[eq.activation]],['Качество',row.instance.metadata?.quality],['Расход Драйва',item.stats?.driveCost],['Длительность',item.stats?.duration],['Перезарядка',item.stats?.cooldown],['Ограничения',item.availability?.restrictions],['Дополнительные зоны',row.zone.additional.map(id=>zones.find(z=>z[0]===id)[1]).join(', ')],['ID справочника',row.instance.catalogId]];const dl=entries=>'<dl class="chrome-facts">'+entries.filter(([,v])=>v!==''&&v!=null).map(([label,value])=>`<div><dt>${h(label)}</dt><dd>${h(value)}</dd></div>`).join('')+'</dl>';
  return `<aside class="chrome-panel chrome-detail" aria-labelledby="chrome-detail-title"><header class="chrome-panel-head"><h2 id="chrome-detail-title">${h(name(item))}</h2></header><div class="chrome-detail-content"><p class="chrome-detail-meta">${h([item.subtype,row.zone.raw||'Системная установка'].filter(Boolean).join(' · '))}</p>${art(row,'chrome-detail-icon')}${item.description?'<p class="chrome-description">'+h(item.description)+'</p>':''}${fx.permanent.length?'<section class="chrome-effect-section"><h3>'+icon('attributes')+'Постоянные бонусы</h3>'+fx.permanent.map(t=>'<p class="chrome-positive">'+h(t)+'</p>').join('')+'</section>':''}${fx.other.length?'<section class="chrome-effect-section"><h3>Другие эффекты</h3>'+fx.other.map(e=>'<p><small>'+h(e.kind)+'</small>'+h(e.text)+'</p>').join('')+'</section>':''}${dl(facts)}${item.rulesText&&item.rulesText!==item.description?'<section class="chrome-effect-section"><h3>Особые правила</h3><p>'+h(item.rulesText)+'</p></section>':''}<details class="chrome-technical"><summary>Технические детали</summary>${dl(technical)}</details></div></aside>`;
 }
 function renderChrome(){const m=model(card,D.catalog),s=state(),selected=selection(m,s);return `<div class="chrome-ui"><div class="chrome-top"><div class="chrome-heading"><h1>Хром</h1><p>Киберимпланты и модификации тела</p></div><div class="chrome-tools">${load(m)}<div class="chrome-actions"><button type="button" data-chrome-inventory>${icon('inventory')}<span>Открыть снаряжение</span></button></div></div></div><div class="chrome-workspace">${body(m,s)}${list(m,s,selected.rows)}${detail(selected.selected,card,D.catalog,D)}</div></div>`;}
 function bind(){document.querySelectorAll('[data-chrome-zone]').forEach(b=>b.onclick=()=>{const s=state();s.zone=b.dataset.chromeZone;render();document.querySelector('.chrome-zone[aria-pressed="true"],.chrome-filters [aria-pressed="true"]')?.focus();});document.querySelectorAll('[data-chrome-select]').forEach(b=>b.onclick=()=>{state().selected=b.dataset.chromeSelect;render();document.querySelector('.chrome-implant.is-selected')?.focus();});document.querySelectorAll('[data-chrome-inventory]').forEach(b=>b.onclick=()=>switchSheetTab('inventory'));const nodes=document.querySelectorAll('[data-body-zone]');if(nodes.length){const m=model(card,D.catalog),s=state();nodes.forEach(el=>{el.classList.toggle('has-installations',m.counts[el.dataset.bodyZone]>0);el.classList.toggle('is-selected',s.zone===el.dataset.bodyZone);});}}
 const api={render:renderChrome,bind,state,zones,placement,installed,model,effects,selection};root.ND_CHROME=api;if(typeof module==='object'&&module.exports)module.exports=api;
})(typeof window==='object'?window:globalThis);
